import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Identity","description":"","frontmatter":{"title":"Identity"},"headers":[],"relativePath":"api/reference/identity.md","filePath":"api/reference/identity.md"}`),a={name:`api/reference/identity.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to “Identity”">​</a></h1><div><p>Operations of the tag <strong>Identity</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="logout" tabindex="-1">End the current session server-side (REQ-164 AC1, ADR-037) <a class="header-anchor" href="#logout" aria-label="Permalink to “End the current session server-side (REQ-164 AC1, ADR-037)”">​</a></h2><p><code>POST /auth/logout</code> · <code>logout</code></p><p>Revokes the current session and its refresh tokens; the response carries <code>OEA-Purge-Local-Data: session-ended</code> so that the Electron client clears its offline cache. For OIDC sessions the response includes the IdP end-session URL if the provider supports RP-initiated logout.</p><p><strong>Access</strong>: any authenticated principal</p><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Session ended</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="localLogin" tabindex="-1">Local login of the system admin account (US-013 AC2, ADR-042) <a class="header-anchor" href="#localLogin" aria-label="Permalink to “Local login of the system admin account (US-013 AC2, ADR-042)”">​</a></h2><p><code>POST /auth/local/login</code> · <code>localLogin</code></p><p>Login name and password. During the setup phase (ADR-042) a correct password creates the session. Afterwards the response is <code>401</code> with problem type <code>urn:oea:problem:second-factor-required</code> and a <code>loginTransaction</code>, which <code>POST /auth/local/login/totp</code> completes with a TOTP code. Wrong login name and wrong password produce the same <code>401 urn:oea:problem:invalid-credentials</code>; repeated failures are throttled (REQ-168). Protected by an origin check (REQ-187).</p><p><strong>Access</strong>: public – no authentication</p><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: LocalLoginRequest</li></ul><h3 id="responses-1" tabindex="-1">Responses <a class="header-anchor" href="#responses-1" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>Session created; the cookie <code>__Host-OEA_SESSION</code> is set</td><td>–</td></tr><tr><td>401</td><td>Invalid credentials, or a second factor is required (with <code>loginTransaction</code>)</td><td>–</td></tr><tr><td>403</td><td>Origin not allowed (problem type <code>urn:oea:problem:csrf-rejected</code>)</td><td><code>urn:oea:problem:csrf-rejected</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="localLoginTotp" tabindex="-1">Second step of the local login with a TOTP code (REQ-171) <a class="header-anchor" href="#localLoginTotp" aria-label="Permalink to “Second step of the local login with a TOTP code (REQ-171)”">​</a></h2><p><code>POST /auth/local/login/totp</code> · <code>localLoginTotp</code></p><p>Completes a login transaction with a TOTP code. Five wrong codes invalidate the transaction (REQ-168 AC2); a code is never accepted twice (REQ-170).</p><p><strong>Access</strong>: public – no authentication</p><h3 id="request-body-1" tabindex="-1">Request body <a class="header-anchor" href="#request-body-1" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: LocalLoginTotpRequest</li></ul><h3 id="responses-2" tabindex="-1">Responses <a class="header-anchor" href="#responses-2" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>Session created with a second factor; the cookie is set</td><td>–</td></tr><tr><td>401</td><td>Wrong code, or the transaction is unknown, expired or invalidated (<code>invalid-credentials</code>)</td><td>–</td></tr><tr><td>403</td><td>Origin not allowed (<code>csrf-rejected</code>)</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="listLoginProviders" tabindex="-1">Enabled OIDC providers offered on the login page (US-001) <a class="header-anchor" href="#listLoginProviders" aria-label="Permalink to “Enabled OIDC providers offered on the login page (US-001)”">​</a></h2><p><code>GET /auth/oidc/providers</code> · <code>listLoginProviders</code></p><p>Lists the enabled providers stored through the admin API, the only source of the OIDC login. Returns identifiers and names only, never client settings.</p><p><strong>Access</strong>: public – no authentication</p><h3 id="responses-3" tabindex="-1">Responses <a class="header-anchor" href="#responses-3" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Enabled providers</td><td>–</td></tr></tbody></table><h2 id="startOidcLogin" tabindex="-1">Start the OIDC login through a provider (US-001, REQ-166) <a class="header-anchor" href="#startOidcLogin" aria-label="Permalink to “Start the OIDC login through a provider (US-001, REQ-166)”">​</a></h2><p><code>GET /auth/oidc/{providerId}/start</code> · <code>startOidcLogin</code></p><p>Redirects the browser to the provider&#39;s authorization endpoint (authorization code flow with PKCE <code>S256</code>, <code>state</code> and <code>nonce</code>) and sets the login cookie <code>__Host-OEA_LOGIN</code> (<code>HttpOnly</code>, <code>Secure</code>, <code>Path=/</code>, <code>SameSite=Lax</code>, 10 minutes), which binds the running login to the browser. A provider that is unknown, disabled or unreachable redirects to <code>&lt;public URL&gt;/login?error=provider-unavailable</code>.</p><p><strong>Access</strong>: public – no authentication</p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>providerId</code></td><td>path</td><td>yes</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>returnTo</code></td><td>query</td><td>no</td><td>string</td><td>Relative path inside the portal to open after the login (default <code>/</code>)</td></tr></tbody></table><h3 id="responses-4" tabindex="-1">Responses <a class="header-anchor" href="#responses-4" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>302</td><td>Redirect to the provider, or to the login page if the provider is unavailable</td><td>–</td></tr><tr><td>400</td><td>Invalid request parameters or malformed body</td><td>–</td></tr></tbody></table><h2 id="completeOidcLogin" tabindex="-1">Callback of the OIDC login (US-001, REQ-004, REQ-166) <a class="header-anchor" href="#completeOidcLogin" aria-label="Permalink to “Callback of the OIDC login (US-001, REQ-004, REQ-166)”">​</a></h2><p><code>GET /auth/oidc/callback</code> · <code>completeOidcLogin</code></p><p>Redirect URI <code>&lt;public URL&gt;/api/v1/auth/oidc/callback</code>. Accepts the callback only with the <code>state</code> of a running login and the matching login cookie (single use), redeems the code with the PKCE verifier, validates the ID token, finds the person through the binding (<code>iss</code>, <code>sub</code>) and creates the session cookie <code>__Host-OEA_SESSION</code>. Every failure redirects to <code>&lt;public URL&gt;/login?error=login-failed</code> without revealing the reason; the reason is audited (REQ-005, REQ-006).</p><p><strong>Access</strong>: public – no authentication</p><h3 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>query</td><td>no</td><td>string</td><td>–</td></tr><tr><td><code>state</code></td><td>query</td><td>no</td><td>string</td><td>–</td></tr><tr><td><code>error</code></td><td>query</td><td>no</td><td>string</td><td>–</td></tr></tbody></table><h3 id="responses-5" tabindex="-1">Responses <a class="header-anchor" href="#responses-5" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>302</td><td>Redirect to the portal (<code>returnTo</code> of the login) or to the login page with an error</td><td>–</td></tr><tr><td>400</td><td>Invalid request parameters or malformed body</td><td>–</td></tr></tbody></table><h2 id="getCurrentPrincipal" tabindex="-1">Caller and effective permissions <a class="header-anchor" href="#getCurrentPrincipal" aria-label="Permalink to “Caller and effective permissions”">​</a></h2><p><code>GET /me</code> · <code>getCurrentPrincipal</code></p><p>Effective permissions with their sources, resolved server-side at request time. Privileged roles are listed with <code>effective: false</code> while the session lacks a second factor (SoD-8). For UI adaptation only; every operation is enforced server-side.</p><p><strong>Access</strong>: any authenticated principal</p><h3 id="responses-6" tabindex="-1">Responses <a class="header-anchor" href="#responses-6" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Current principal</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="startTotpEnrollment" tabindex="-1">Start the enrollment of a TOTP second factor (REQ-171, ADR-042) <a class="header-anchor" href="#startTotpEnrollment" aria-label="Permalink to “Start the enrollment of a TOTP second factor (REQ-171, ADR-042)”">​</a></h2><p><code>POST /me/second-factors/totp</code> · <code>startTotpEnrollment</code></p><p>Requires an authentication within the last 5 minutes (REQ-172), otherwise <code>401</code> with problem type <code>urn:oea:problem:reauthentication-required</code>. Returns the secret once; the credential stays <code>pending</code> until confirmed (10 minutes).</p><p><strong>Access</strong>: any authenticated principal</p><h3 id="request-body-2" tabindex="-1">Request body <a class="header-anchor" href="#request-body-2" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: TotpEnrollmentRequest</li></ul><h3 id="responses-7" tabindex="-1">Responses <a class="header-anchor" href="#responses-7" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>Enrollment started</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="confirmTotpEnrollment" tabindex="-1">Confirm a TOTP enrollment with a valid code <a class="header-anchor" href="#confirmTotpEnrollment" aria-label="Permalink to “Confirm a TOTP enrollment with a valid code”">​</a></h2><p><code>POST /me/second-factors/totp/{credentialId}/confirm</code> · <code>confirmTotpEnrollment</code></p><p>Activates the credential and marks the current session as confirmed with a second factor; an audit event <code>auth.factor-added</code> is written (REQ-172 AC3).</p><p><strong>Access</strong>: any authenticated principal</p><h3 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>credentialId</code></td><td>path</td><td>yes</td><td>string (uuid)</td><td>–</td></tr></tbody></table><h3 id="request-body-3" tabindex="-1">Request body <a class="header-anchor" href="#request-body-3" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: TotpConfirmation</li></ul><h3 id="responses-8" tabindex="-1">Responses <a class="header-anchor" href="#responses-8" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Second factor active; the session is confirmed with it</td><td>–</td></tr><tr><td>400</td><td>Invalid code (problem type <code>urn:oea:problem:invalid-totp-code</code>)</td><td><code>urn:oea:problem:invalid-totp-code</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};